from sqlalchemy import Column, Integer, String
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import DeclarativeBase
class Base(DeclarativeBase): pass
class Item(Base):
    __tablename__ = 'items'
    id = Column(Integer, primary_key=True)
    name = Column(String, unique=True, nullable=False)
def import_rows(session, records):
    accepted = []
    rejected = []

    # begin_nested() flushes pending changes before opening its savepoint.
    session.flush()
    connection = session.connection(bind_arguments={'mapper': Item})
    if connection.dialect.name == 'sqlite':
        # SQLite legacy transaction control does not begin on SAVEPOINT.
        if not connection.connection.driver_connection.in_transaction:
            connection.exec_driver_sql('BEGIN')

    for position, row in enumerate(records):
        try:
            with session.begin_nested():
                item = Item(**row)
                session.add(item)
                session.flush()
        except IntegrityError:
            rejected.append(position)
        else:
            accepted.append(item.id)

    return {'accepted': accepted, 'rejected': rejected}
